export const BODY: string = "\n<p>فیویکن بنانا تکنیکی لگتا ہے، مگر درست ٹول کے ساتھ اس میں صرف چند منٹ لگتے ہیں۔ آپ لوگو اپ لوڈ کرتے ہیں، کچھ ترتیبات ایڈجسٹ کرتے ہیں، فائلوں کا پیک ڈاؤن لوڈ کرتے ہیں اور اپنی ویب سائٹ میں مختصر سنیپٹ شامل کرتے ہیں۔ یہ رہنما ہر مرحلہ ترتیب سے بتاتا ہے۔</p>\n<p>شروع کرنے سے پہلے آپ کو صرف دو چیزیں چاہییں: ایک لوگو فائل اور اپنی ویب سائٹ فائلوں تک رسائی۔ مربع PNG یا SVG لوگو بہترین کام کرتا ہے، اور آپ کے پاس سب سے بڑا ورژن تیز ترین نتیجہ دیتا ہے۔ اگر صرف JPG ہو تو وہ بھی کام کرتا ہے۔</p>\n<p><a href=\"/ur/favicon-generator/\">فیویکن جنریٹر</a> پورا کام آپ کے براؤزر میں کرتا ہے۔ آپ کا لوگو کبھی آپ کے آلے سے نہیں جاتا، اکاؤنٹ بنانے کی ضرورت نہیں، اور تیار پیک ZIP کے طور پر ڈاؤن لوڈ ہوتا ہے۔ نیچے کے مراحل پر عمل کریں اور آپ کی سائٹ کے پاس مکمل آئیکن سیٹ ہو گا۔</p>\n<h2 id=\"step-1-prepare-your-logo\">مرحلہ 1: اپنا لوگو تیار کریں</h2>\n<p>اپنی لوگو فائل کھولیں اور جانچیں کہ یہ مربع ہے، یا اس کے قریب۔ مربع کینوس چھوٹی فیویکن جگہ بہترین استعمال کرتا ہے، جبکہ چوڑا مستطیل لوگو نشان کے اوپر اور نیچے خالی پٹیاں چھوڑ دیتا ہے۔ اگر آپ کا لوگو چوڑا ہو تو مربع تفصیل کراپ کریں یا ایک حرف والا ورژن استعمال کریں۔</p>\n<p>ریزولوشن جانچیں۔ 512 بہ 512 پکسل یا اس سے بڑا ماخذ ہر فیویکن سائز تک صاف سکڑتا ہے۔ اینڈرائیڈ کے لیے 512 پکسل تک کھینچا گیا 64 پکسل ماخذ نرم لگتا ہے، اس لیے ہمیشہ آپ کے پاس سب سے بڑی فائل استعمال کریں۔ SVG فائل مثالی ہے کیونکہ اس کی کوئی مقررہ ریزولوشن نہیں۔</p>\n<p>اگر آرٹ ورک میں چھوٹا متن یا باریک تفصیل ہو تو اسے سادہ کریں۔ ورڈ مارک کے نیچے ٹیگ لائن 16 پکسل پر بچ نہیں پائے گی، اس لیے اسے فیویکن ورژن سے ہٹا دیں۔ سب سے بولڈ عنصر رکھیں: نشان، حرف، یا سب سے مضبوط شکل۔</p>\n<h2 id=\"step-2-upload-to-the-generator\">مرحلہ 2: جنریٹر میں اپ لوڈ کریں</h2>\n<p>فیویکن جنریٹر کھولیں اور اپنا لوگو اپ لوڈ والے حصے پر گھسیٹ دیں، یا اپنے آلے سے فائل چننے کے لیے اس پر کلک کریں۔ آپ Ctrl+V سے کلپ بورڈ سے کاپی شدہ تصویر بھی سیدھی چسپاں کر سکتے ہیں، جو اس وقت مفید ہے جب لوگو دوسری ایپ میں کھلا ہو۔</p>\n<p>ٹول 20 MB تک PNG، SVG، JPG، WebP اور HEIC فائلیں قبول کرتا ہے۔ زیادہ تر لوگو اس حد سے کہیں چھوٹے ہوتے ہیں، اس لیے سائز شاذ ہی مسئلہ بنتا ہے۔ اگر آپ کی فائل آئی فون کی HEIC تصویر ہو تو وہ بغیر کسی اضافی مرحلے کے اپ لوڈ اور بدل جاتی ہے۔</p>\n<p>جیسے ہی فائل لوڈ ہوتی ہے، جنریٹر آئیکن پیک کا پیش نظارہ بناتا ہے۔ آپ کو نشان کئی سائز میں رینڈر شدہ دکھائی دے گا، تاکہ آپ فیصلہ کر سکیں کہ وہ چھوٹا اور بڑا کیسا پڑھتا ہے۔ اگر لوگو 16 پکسل پر غلط لگے تو ماخذ تصویر ابھی درست کریں، بعد میں نہیں۔</p>\n<h2 id=\"step-3-set-padding-and-shape\">مرحلہ 3: پیڈنگ اور شکل طے کریں</h2>\n<p>پیڈنگ آپ کے لوگو اور آئیکن کنارے کے درمیان خالی جگہ ہے۔ تھوڑی سی سے شروع کریں، اتنی کہ نشان کینوس کنارے کو نہ چھوئے۔ کنارے سے دبا ہوا لوگو تنگ لگتا ہے، خاص طور پر ٹیب سائز پر جہاں ہر پکسل اہم ہے۔</p>\n<p>اگر لوگو میں باریک کنارے یا پتلی لکیریں ہوں تو پیڈنگ بڑھائیں۔ پتلی تفصیل کو سانس لینے کی جگہ چاہیے، ورنہ وہ چھوٹے سائز پر کنارے سے مل جاتی ہے۔ اگر نشان بولڈ اور سادہ ہو تو اسے کم کریں، کیونکہ بولڈ شکل کینوس کا زیادہ حصہ محفوظ طریقے سے بھر سکتی ہے۔</p>\n<p>کونے کا رداس آئیکن پس منظر کے کونے گول کرتا ہے۔ ہلکی گولائی نشان کی شخصیت بدلے بغیر نظر نرم کرتی ہے۔ مکمل گولائی آئیکن کو دائرہ بنا دیتی ہے، جو اوتار اور ایپ جیسے آئیکن کو سوٹ کرتی ہے مگر مربع لوگو کو عجیب کراپ کر سکتی ہے۔</p>\n<h2 id=\"step-4-choose-a-background-fill\">مرحلہ 4: پس منظر کا بھرنا چنیں</h2>\n<p>پس منظر کا بھرنا شفاف لوگو کے پیچھے کا رنگ ہے۔ اسے شفاف چھوڑنے سے آئیکن ہلکا رہتا ہے اور براؤزر ٹیب کا رنگ دکھائی دیتا ہے۔ یہ ہلکے ٹیب پر گہرے، بولڈ لوگو کے لیے اچھا کام کرتا ہے۔</p>\n<p>جب لوگو پیلا، پتلا یا ہلکے رنگ کا ہو تو ٹھوس بھرنا شامل کریں۔ نشان کے پیچھے سفید یا برانڈ رنگ والا مربع کسی بھی ٹیب پر اسے تضاد دیتا ہے۔ اپنے برانڈ سے میل کھانے والا بھرنا چنیں، کیونکہ یہ رنگ آئیکن شناخت کا حصہ بن جاتا ہے۔</p>\n<p>ایپل ٹچ آئیکن شفافیت کو نظرانداز کرتے ہیں اور خالی جگہیں کالے سے بھرتے ہیں، اس لیے ہوم اسکرین آئیکن کے لیے ٹھوس بھرنا محفوظ انتخاب ہے۔ اگر آپ کا ٹیب فیویکن شفاف رہے مگر ایپل آئیکن کو بھرنا چاہیے تو جنریٹر دونوں کو انہی ترتیبات سے سنبھالتا ہے۔</p>\n<h2 id=\"step-5-check-the-previews\">مرحلہ 5: پیش نظارے جانچیں</h2>\n<p>جنریٹر آپ کا آئیکن ہلکے اور گہرے براؤزر ٹیب پر دکھاتا ہے۔ اگر آپ کا لوگو گہرا ہو تو پہلے گہرا پیش نظارہ دیکھیں، اور اگر لوگو ہلکا ہو تو پہلے ہلکا پیش نظارہ دیکھیں۔ جہاں آپ کے لوگو کا رنگ ٹیب رنگ سے میل کھاتا ہے، وہیں مسائل ظاہر ہوتے ہیں۔</p>\n<p>اپنی توجہ سب سے چھوٹے پیش نظارے، 16 پکسل ٹیب آئیکن پر مرکوز کریں۔ یہ وہ سائز ہے جو زائرین اکثر دیکھتے ہیں، اور یہی وہ جگہ ہے جہاں تفصیل مر جاتی ہے۔ اگر آپ اس سائز پر بھی نشان پہچان سکیں تو فیویکن کام کرتا ہے۔ اگر وہ دھبہ بن جائے تو ماخذ سادہ کریں یا پیڈنگ بڑھائیں۔</p>\n<p>سب سے بڑے پیش نظارے، 512 پکسل اینڈرائیڈ آئیکن پر بھی نظر ڈالیں۔ چھوٹے پر اچھا پڑھنے والا نشان بڑے سائز پر خالی یا گمشدہ لگ سکتا ہے، خاص طور پر اگر وہ ایک پتلا حرف ہو۔ بڑا پیش نظارہ دکھاتا ہے کہ ڈیزائن ہوم اسکرین پر قائم رہتا ہے یا نہیں۔</p>\n<h2 id=\"step-6-download-the-pack\">مرحلہ 6: پیک ڈاؤن لوڈ کریں</h2>\n<p>جب پیش نظارے درست لگیں تو ZIP ڈاؤن لوڈ کریں۔ اندر آپ کو favicon.ico، ایپل ٹچ آئیکن، 192 اور 512 پکسل پر اینڈرائیڈ آئیکن، site.webmanifest فائل اور HTML سنیپٹ ملیں گے۔ سب نامزد اور اپ لوڈ کے لیے تیار ہیں۔</p>\n<p>اگر صرف ایک فائل چاہیے تو آپ اکیلی فائلیں بھی ڈاؤن لوڈ کر سکتے ہیں۔ صرف favicon.ico لینا پرانی سائٹ پر فوری درست کرنے کے لیے کافی ہے، جبکہ مکمل ZIP نئی سائٹ کے لیے درست انتخاب ہے جسے پورا سیٹ چاہیے۔</p>\n<p>اپ لوڈ سے پہلے اپنے کمپیوٹر پر پیک ان زپ کریں اور فائلیں دیکھیں۔ جانچیں کہ آئیکن سائز موجود ہیں اور مینیفیسٹ فائل شامل ہے۔ اب فوری نظر سائٹ میں ترمیم کے بعد گم شدہ فائل کی حیرانی سے بچاتی ہے۔</p>\n<h2 id=\"step-7-upload-the-files\">مرحلہ 7: فائلیں اپ لوڈ کریں</h2>\n<p>آئیکن فائلیں اپنی ویب سائٹ کے روٹ فولڈر میں اپ لوڈ کریں، وہی فولڈر جس میں آپ کا ہوم پیج ہے۔ براؤزر پہلے سے طے شدہ طور پر روٹ پر favicon.ico ڈھونڈتے ہیں، اس لیے اسے وہاں رکھنے سے وہ صفحے بھی پورے ہوتے ہیں جن میں سنیپٹ شامل نہیں۔</p>\n<p>فائلیں کاپی کرنے کے لیے اپنے ہوسٹنگ فائل مینیجر، FTP کلائنٹ یا ڈیپلائمنٹ ٹول کا استعمال کریں۔ فائلیں چھوٹی ہیں، اس لیے اپ لوڈ میں سیکنڈ لگتے ہیں۔ تصدیق کریں کہ ہر فائل روٹ میں گئی، غلطی سے کسی سب فولڈر میں نہیں۔</p>\n<p>اگر آپ کا سائٹ بلڈر روٹ فولڈر نہیں دکھاتا تو اس کے ڈیش بورڈ میں فیویکن یا سائٹ آئیکن ترتیب ڈھونڈیں۔ کئی بلڈر اپ لوڈ شدہ آئیکن قبول کرتے ہیں اور فائل رکھنے کا کام خود سنبھالتے ہیں۔ اس صورت میں 512 پکسل PNG اپ لوڈ کریں، کیونکہ بلڈر عام طور پر بڑے ماخذ سے سائز بدلتے ہیں۔</p>\n<h2 id=\"step-8-add-the-html-snippet\">مرحلہ 8: HTML سنیپٹ شامل کریں</h2>\n<p>پیک کے ساتھ آیا HTML سنیپٹ کھولیں۔ اس میں فیویکن، ایپل ٹچ آئیکن اور ویب مینیفیسٹ کے لیے لنک ٹیگ ہیں۔ پورا بلاک بالکل ویسا ہی کاپی کریں جیسا دیا گیا ہے، راستوں میں ترمیم کیے بغیر۔</p>\n<p>سنیپٹ کو اپنے صفحات کے head حصے میں چسپاں کریں، دوسرے میٹا اور لنک ٹیگ کے قریب۔ سادہ HTML سائٹ پر اسے ہر صفحے یا مشترکہ ہیڈر ٹیمپلیٹ میں شامل کریں۔ ری ایکٹ یا نیکسٹ جے ایس میں اسے ایک بار اس لے آؤٹ یا دستاویز فائل میں شامل کریں جو ہر صفحہ شیئر کرتا ہے۔</p>\n<p>فائل محفوظ کریں اور براؤزر میں اپنی سائٹ دوبارہ لوڈ کریں۔ ٹیب آئیکن آپ کے نئے فیویکن میں بدلنا چاہیے۔ اگر نہ بدلے تو پرانا آئیکن کیش میں ہو سکتا ہے، جو عام ہے اور اگلے مرحلے میں بتایا گیا ہے۔</p>\n<h2 id=\"step-9-clear-the-cache-and-test\">مرحلہ 9: کیش صاف کریں اور آزمائیں</h2>\n<p>براؤزر فیویکن کو لمبے عرصے تک کیش کرتے ہیں، اس لیے آپ کا اپنا براؤزر اپ لوڈ کے بعد بھی پرانا آئیکن دکھا سکتا ہے۔ Ctrl، Shift اور R سے ہارڈ ریفریش کریں، یا فیویکن URL سیدھا کھولیں اور اس صفحے کو ریفریش کر کے تازہ لانے پر مجبور کریں۔</p>\n<p>آئیکن دوسرے براؤزر یا پرائیویٹ ونڈو میں آزمائیں، جہاں کیش خالی ہوتی ہے۔ پرائیویٹ ونڈو دکھاتی ہے کہ نیا زائر کیا دیکھتا ہے، جو ایماندارانہ آزمائش ہے۔ اگر آئیکن وہاں دکھائی دے تو اپ لوڈ درست ہوا اور صرف آپ کے مرکزی براؤزر کا کیش پرانا ہے۔</p>\n<p>سائٹ کو اپنے فون کی ہوم اسکرین میں شامل کریں اور ایپل یا اینڈرائیڈ آئیکن جانچیں۔ ہوم اسکرین آئیکن سب سے بڑا ورژن ہے، اس لیے وہ وہ خامیاں دکھاتا ہے جو ٹیب پیش نظارہ چھپاتا ہے۔ اگر وہ فون پر درست لگے تو پیک مکمل ہے۔</p>\n<h2 id=\"step-10-when-to-regenerate\">مرحلہ 10: کب دوبارہ بنائیں</h2>\n<p>جب بھی آپ کا لوگو بدلے، چاہے تھوڑا ہی ہو، پیک دوبارہ بنائیں۔ نیا ورڈ مارک، نیا برانڈ رنگ یا بہتر نشان، سب تازہ پیک کے مستحق ہیں، کیونکہ پرانا فیویکن نئی برانڈنگ کی ہر جگہ خاموشی سے تردید کرتا ہے۔</p>\n<p>ایک فائل بدلنے کی بجائے پورا پیک دوبارہ بنائیں۔ صرف favicon.ico بدلنے سے پرانا نشان ہوم اسکرینوں اور مینیفیسٹ میں رہ جاتا ہے، جس سے آلات پر پرانے اور نئے آئیکن کا الجھا ہوا مرکب بن جاتا ہے۔</p>\n<p>اگر آپ سائٹ کا نام یا تھیم رنگ بدلیں تو مینیفیسٹ بھی اپ ڈیٹ کریں۔ جنریٹر ہر پیک کے ساتھ تازہ مینیفیسٹ لکھتا ہے، اس لیے دوبارہ بنانے سے نام، رنگ اور آئیکن JSON میں ہاتھ ڈالے بغیر ہم آہنگ رہتے ہیں۔</p>\n<h2 id=\"quick-reference\">فوری حوالہ: فیویکن بنانے کی چیک لسٹ</h2>\n<p>کم از کم 512 پکسل والا مربع PNG یا SVG لوگو تیار کریں، چھوٹا متن ہٹا دیں۔ اسے جنریٹر میں اپ لوڈ کریں، پیڈنگ اور کونے کا رداس طے کریں، پس منظر کا بھرنا چنیں اور سب سے چھوٹے سائز پر ہلکے اور گہرے پیش نظارے جانچیں۔</p>\n<p>ZIP ڈاؤن لوڈ کریں، فائلیں سائٹ روٹ میں اپ لوڈ کریں، سنیپٹ مشترکہ head ٹیمپلیٹ میں چسپاں کریں اور پرائیویٹ ونڈو اور اپنے فون پر آزمائیں۔ اگر پرانا آئیکن رہ جائے تو کیش صاف کریں۔</p>\n<p>پیک کی ہر فائل کا مکمل پس منظر جاننے کے لیے <a href=\"/ur/blog/favicon-generator-rehnumai/\">Favicon Generator: Complete Guide</a> پڑھیں، اور سائز بہ سائز تفصیل کے لیے <a href=\"/ur/blog/favicon-sizes-wazahat/\">Favicon Sizes Explained: 16×16 to 512×512</a> دیکھیں۔ ابھی <a href=\"/ur/favicon-generator/\">فیویکن جنریٹر</a> سے شروع کریں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"فیویکن بنانے کے لیے کون سی لوگو فائل استعمال کروں؟","answer":"کم از کم 512 پکسل والا مربع PNG یا SVG لوگو بہترین کام کرتا ہے۔ SVG مثالی ہے کیونکہ وہ ہر سائز تک صاف اسکیل ہوتا ہے۔ JPG بھی کام کرتا ہے، مگر اس میں شفافیت نہیں ہوتی، اس لیے PNG یا SVG آپ کو پس منظر پر زیادہ کنٹرول دیتا ہے۔"},{"question":"میرا نیا فیویکن فوراً کیوں نہیں دکھائی دیتا؟","answer":"براؤزر فیویکن کو جارحانہ انداز سے کیش کرتے ہیں، کبھی ہفتوں تک۔ ہارڈ ریفریش کریں، فیویکن URL سیدھا کھولیں اور اسے ریفریش کریں، یا پرائیویٹ ونڈو میں آزمائیں۔ نیا آئیکن دوسرے زائرین کو تب دکھائی دیتا ہے جب ان کا کیش ختم ہو، یا فوراً اگر آپ آئیکن لنک میں ورژن نمبر شامل کریں۔"},{"question":"فیویکن فائلیں ویب سائٹ پر کہاں رکھوں؟","answer":"انہیں اپنی ویب سائٹ کے روٹ فولڈر میں اپ لوڈ کریں، وہی فولڈر جہاں آپ کا ہوم پیج ہے۔ براؤزر پہلے سے طے شدہ طور پر روٹ پر favicon.ico ڈھونڈتے ہیں۔ پھر HTML سنیپٹ صفحات کے head حصے میں چسپاں کریں تاکہ براؤزر ایپل آئیکن اور مینیفیسٹ بھی ڈھونڈ سکے۔"},{"question":"کیا HTML سنیپٹ ہر صفحے میں شامل کرنا ضروری ہے؟","answer":"اسے ایک بار مشترکہ head ٹیمپلیٹ یا لے آؤٹ فائل میں شامل کریں جو ہر صفحہ استعمال کرتا ہے۔ سادہ HTML سائٹ پر اس کا مطلب ہیڈر انکلوڈ ہے؛ ری ایکٹ یا نیکسٹ جے ایس میں اس کا مطلب لے آؤٹ یا دستاویز فائل ہے۔ آپ کو اسے ہر صفحے میں ہاتھ سے چسپاں کرنے کی ضرورت نہیں۔"},{"question":"کیا فون کی تصویر سے فیویکن بنا سکتا ہوں؟","answer":"جی ہاں، جنریٹر آئی فون کی HEIC تصاویر کے ساتھ ساتھ JPG اور PNG فائلیں بھی قبول کرتا ہے۔ مگر 16 پکسل پر تصویر شاذ ہی اچھا فیویکن بناتی ہے، اس لیے بہترین نتیجے کے لیے پہلے بولڈ تفصیل یا ایک مضبوط شکل پر کراپ کریں۔"},{"question":"اگر میرا لوگو مربع نہ ہو تو کیا کروں؟","answer":"جنریٹر مستطیل لوگو کو کھینچے بغیر مربع کینوس کے اندر فٹ کرتا ہے، مگر نتیجہ اطراف میں خالی جگہ کے ساتھ چھوٹا لگ سکتا ہے۔ بہترین نتیجے کے لیے اپنے نشان کا مربع ورژن تیار کریں، یا اپ لوڈ سے پہلے سب سے پہچانی جانے والی تفصیل پر کراپ کریں۔"}];
